package com.example.lending.application.service;

import com.example.lending.application.port.in.ListMemberLoansUseCase;
import com.example.lending.application.port.out.LoadActiveLoansPort;
import com.example.lending.application.port.out.LoadActiveLoansPort.ActiveLoanPage;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Transactional(readOnly = true)
public class ListMemberLoansService implements ListMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadActiveLoansPort loadActiveLoansPort;
    private final LoadBookPort loadBookPort;

    public ListMemberLoansService(LoadMemberPort loadMemberPort, LoadActiveLoansPort loadActiveLoansPort,
                                  LoadBookPort loadBookPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadActiveLoansPort = loadActiveLoansPort;
        this.loadBookPort = loadBookPort;
    }

    @Override
    public MemberLoanPage listMemberLoans(ListMemberLoansQuery query) {
        loadMemberPort.loadMember(query.memberId())
                .orElseThrow(() -> new MemberNotFoundException(query.memberId()));

        ActiveLoanPage loanPage = loadActiveLoansPort.loadActiveLoans(query.memberId(), query.page(), query.size());
        List<MemberLoanItem> items = loanPage.loans().stream().map(this::toItem).toList();
        return new MemberLoanPage(items, query.page(), query.size(), loanPage.totalCount());
    }

    private MemberLoanItem toItem(Loan loan) {
        Book book = loadBookPort.loadBook(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        return new MemberLoanItem(loan.getId(), loan.getBookId(), book.getTitle(), loan.getLoanedAt(), loan.getDueAt());
    }
}

