package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoansIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void lists_active_loans_by_page_with_total_count() throws Exception {
        String memberId = registerMember("페이지 회원");
        String returnedLoanId = loan(registerBook("반납한 책"), memberId, "2026-02-01");
        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId)).andExpect(status().isOk());
        loan(registerBook("Clean Code"), memberId, "2026-02-02");
        loan(registerBook("Refactoring"), memberId, "2026-02-03");
        loan(registerBook("Effective Java"), memberId, "2026-02-04");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3))
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.items[0].loanId").isString())
                .andExpect(jsonPath("$.items[0].bookId").isString())
                .andExpect(jsonPath("$.items[1].title").value("Refactoring"));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount").value(3))
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Effective Java"));
    }

    @Test
    void page_past_the_end_returns_empty_items_with_total_count() throws Exception {
        String memberId = registerMember("빈 페이지 회원");
        loan(registerBook("한 권만 빌림"), memberId, "2026-02-02");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "5").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void does_not_include_other_members_loans() throws Exception {
        String memberId = registerMember("이 회원");
        String otherMemberId = registerMember("다른 회원");
        loan(registerBook("내 책"), memberId, "2026-02-02");
        loan(registerBook("남의 책"), otherMemberId, "2026-02-02");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount").value(1))
                .andExpect(jsonPath("$.items[0].title").value("내 책"));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID().toString()))
                .andExpect(status().isNotFound());
    }

    @Test
    void invalid_page_or_size_returns_400() throws Exception {
        String memberId = registerMember("잘못된 입력 회원");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "101"))
                .andExpect(status().isBadRequest());
    }

    private String registerMember(String name) throws Exception {
        String body = mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String body = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("id").asText();
    }

    private String loan(String bookId, String memberId, String loanedAt) throws Exception {
        String body = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                                + "\",\"loanedAt\":\"" + loanedAt + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("loanId").asText();
    }
}

